    private int rowNumber;

    private String reportGroup;

    private String type;

    private String propertyCode;

    PbcReportEnums(int rowNumber, String reportGroup, String type, String propertyCode) {
        this.rowNumber = rowNumber;
        this.reportGroup = reportGroup;
        this.type = type;
        this.propertyCode = propertyCode;
    }

    public int getRowNumber() {
        return rowNumber;
    }

    public String getReportGroup() {
        return reportGroup;
    }

    public String getType() {
        return type;
    }

    public String getPropertyCode() {
        return propertyCode;
    }

    public static List<PbcReportEnums> getPropertiesByType(String reportType,String group){
        List<PbcReportEnums> reportEnums = new ArrayList<>();
        for (PbcReportEnums value : PbcReportEnums.values()) {
            if(value.type.equals(reportType) && value.reportGroup.equals(group)){
                reportEnums.add(value);
            }
        }
        return reportEnums;
    }
    public static List<PbcReportEnums> getPropertiesByType(String reportType,String group,int rowNumber){
        List<PbcReportEnums> reportEnums = new ArrayList<>();
        for (PbcReportEnums value : PbcReportEnums.values()) {
            if(value.type.equals(reportType) && value.reportGroup.equals(group)&& value.rowNumber == rowNumber){
                reportEnums.add(value);
            }
        }
        return reportEnums;
    }
